package io.github.rebrowser.engine;
import static org.junit.Assert.*;
import java.io.*;
import java.lang.reflect.*;
import org.junit.Test;
import org.mozilla.geckoview.GeckoSession;
/** Actual native reject methods with SYNTHETIC SDK callback objects/streams, no GeckoResult/JNI. */
public final class TemporaryHostBoundaryTest {
 private static Object adapter(SessionPresentation m)throws Exception{Class<?> c=Class.forName("io.github.rebrowser.engine.BrowserSessionHost$Events");Constructor<?> ctor=c.getDeclaredConstructor(SessionPresentation.class);assertTrue(Modifier.isPrivate(ctor.getModifiers()));ctor.setAccessible(true);return ctor.newInstance(m);}
 private static NavigationDelegate.Observation navigation(NavigationDelegate.Event e,String url,Boolean flag)throws Exception{Constructor<NavigationDelegate.Observation> c=NavigationDelegate.Observation.class.getDeclaredConstructor(long.class,NavigationDelegate.Event.class,String.class,Boolean.class,NavigationDelegate.Decision.class);c.setAccessible(true);return c.newInstance(1,e,url,flag,null);}
 private static ProgressDelegate.Loading loading(ProgressDelegate.Event e,int progress,Boolean success)throws Exception{Constructor<ProgressDelegate.Loading> c=ProgressDelegate.Loading.class.getDeclaredConstructor(long.class,ProgressDelegate.Event.class,String.class,int.class,Boolean.class);c.setAccessible(true);return c.newInstance(1,e,null,progress,success);}
 @Test public void actualPrivateNavigationAdapterRoutesSessionLocationNotDocument()throws Exception{SessionPresentation m=new SessionPresentation();NavigationDelegate.NativeObserver a=(NavigationDelegate.NativeObserver)adapter(m);a.observed(navigation(NavigationDelegate.Event.LOCATION,"https://display/",true));assertEquals("https://display/",m.snapshot().reportedLocation());assertEquals(1,m.snapshot().observationSequence());}
 @Test public void actualPrivateAdapterRoutesIndependentHistoryCapabilities()throws Exception{SessionPresentation m=new SessionPresentation();NavigationDelegate.NativeObserver a=(NavigationDelegate.NativeObserver)adapter(m);a.observed(navigation(NavigationDelegate.Event.BACK_CAPABILITY,null,true));a.observed(navigation(NavigationDelegate.Event.FORWARD_CAPABILITY,null,false));assertTrue(m.snapshot().reportedCanGoBack());assertFalse(m.snapshot().reportedCanGoForward());}
 @Test public void loadErrorAndBlockedLoadCannotBecomeSuccessfulDocument()throws Exception{SessionPresentation m=new SessionPresentation();NavigationDelegate.NativeObserver a=(NavigationDelegate.NativeObserver)adapter(m);for(NavigationDelegate.Event e:new NavigationDelegate.Event[]{NavigationDelegate.Event.LOAD_ERROR,NavigationDelegate.Event.BLOCKED_LOAD,NavigationDelegate.Event.BLOCKED_NEW_WINDOW})a.observed(navigation(e,"https://not-loaded/",null));assertNull(m.snapshot().reportedLocation());assertEquals(0,m.snapshot().observationSequence());}
 @Test public void actualProgressAdapterRoutesMonotonicLoadAndStopWithoutFalseHundred()throws Exception{SessionPresentation m=new SessionPresentation();ProgressDelegate.NativeObserver a=(ProgressDelegate.NativeObserver)adapter(m);a.loading(loading(ProgressDelegate.Event.REPORTED_START,0,null));a.loading(loading(ProgressDelegate.Event.REPORTED_PROGRESS,60,null));a.loading(loading(ProgressDelegate.Event.REPORTED_PROGRESS,10,null));a.loading(loading(ProgressDelegate.Event.REPORTED_STOP,60,true));assertEquals(60,m.snapshot().reportedProgress());assertEquals(Boolean.TRUE,m.snapshot().reportedStopSuccess());assertFalse(m.snapshot().loadingObserved());}
 @Test public void retiredModelIgnoresActualLateAdapterMessages()throws Exception{SessionPresentation m=new SessionPresentation();Object a=adapter(m);m.retire();((NavigationDelegate.NativeObserver)a).observed(navigation(NavigationDelegate.Event.LOCATION,"https://late/",true));((ProgressDelegate.NativeObserver)a).loading(loading(ProgressDelegate.Event.REPORTED_START,0,null));assertTrue(m.snapshot().retired());assertNull(m.snapshot().reportedLocation());assertFalse(m.snapshot().loadingObserved());}
 @Test public void actualCheckpointAdapterRejectsWithoutSerializationOrReceiverOwnership()throws Exception{ProgressDelegate.NativeObserver a=(ProgressDelegate.NativeObserver)adapter(new SessionPresentation());assertFalse(a.checkpoint(null));}
 @Test public void androidRequestRejectsOnceNeverGrantsOrPrompts(){int[] calls=new int[2];new PermissionDelegate().onAndroidPermissionsRequest(null,new String[]{"android.permission.CAMERA"},new GeckoSession.PermissionDelegate.Callback(){public void grant(){calls[0]++;}public void reject(){calls[1]++;}});assertArrayEquals(new int[]{0,1},calls);}
 @Test public void mediaRequestRejectsWithoutInspectingOrGrantingSources(){int[] rejected={0};new PermissionDelegate().onMediaPermissionRequest(null,"https://not-authority/",null,null,new GeckoSession.PermissionDelegate.MediaCallback(){public void grant(String v,String a){fail();}public void grant(GeckoSession.PermissionDelegate.MediaSource v,GeckoSession.PermissionDelegate.MediaSource a){fail();}public void reject(){rejected[0]++;}});assertEquals(1,rejected[0]);}
 @Test public void absentSyntheticCallbacksDoNotMintPositiveDecisions(){PermissionDelegate d=new PermissionDelegate();d.onAndroidPermissionsRequest(null,null,null);d.onMediaPermissionRequest(null,null,null,null,null);}
 @Test public void rejectedBodyClosesExactlyOnceNeverReads(){int[] closes={0};InputStream body=new InputStream(){public int read(){throw new AssertionError("No read/drain");}public void close(){closes[0]++;}};assertTrue(ContentDelegate.closeRejectedBody(body));assertEquals(1,closes[0]);}
 @Test public void absentBodyRequiresNoAlternateFetch(){assertTrue(ContentDelegate.closeRejectedBody(null));}
 @Test public void ioCloseFailureIsUnknownNotSuccessOrRetry(){int[] closes={0};assertFalse(ContentDelegate.closeRejectedBody(new InputStream(){public int read(){throw new AssertionError();}public void close()throws IOException{closes[0]++;throw new IOException("synthetic");}}));assertEquals(1,closes[0]);}
 @Test public void runtimeCloseFailureIsUnknownNotPublication(){assertFalse(ContentDelegate.closeRejectedBody(new InputStream(){public int read(){throw new AssertionError();}public void close(){throw new IllegalStateException("synthetic");}}));}
}
